<?php requireRole('student'); ?><section class="hero"><h1>Student Dashboard 🎮</h1><p>Learn coding, earn XP, build streaks and unlock achievements.</p></section><div id="stats" class="stat-grid"></div><div class="actions"><a class="btn" href="index.php?page=courses">Browse Courses</a><a class="btn secondary" href="index.php?page=leaderboard">🏆 Leaderboard</a></div><h2>My Courses</h2><div id="courses" class="grid"></div><script>async function load(){let d=await api('backend/api/progress.php');let u=d.user;document.getElementById('stats').innerHTML=`<div class="stat">⭐ XP<strong>${u.xp}</strong></div><div class="stat">🏆 Level<strong>${u.level}</strong></div><div class="stat">🔥 Streak<strong>${u.streak}</strong></div><div class="stat">👤 Student<strong>${escapeHTML(u.full_name)}</strong></div>`;document.getElementById('courses').innerHTML=d.courses.length?d.courses.map(c=>`<div class="card"><h2>${escapeHTML(c.title)}</h2><p>${c.percent_complete}% complete</p><div class="progress"><div style="width:${c.percent_complete}%"></div></div><br><a class="btn" href="index.php?page=lesson&course_id=${c.id}">Continue</a></div>`).join(''):'<div class="card"><h2>Start learning 🚀</h2><a class="btn" href="index.php?page=courses">Browse courses</a></div>'}load()</script>
